{
  "status": "SUPPORTED",
  "task_summary": "Set up refreshment stations near seating and move control to accessible location.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds drinkware and plates for consumption",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["cup", "plate", "napkin"],
      "required_properties": ["holds liquid", "holds food"]
      }
    ,
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["remote control"],
      "required_properties": ["has buttons"]
      }
    ,
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Displays video for viewing",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["screen"],
      "required_properties": ["displays video"]
      }
    ,
      {
        "id": "seating_spot",
        "entity_kind": "REGION",
        "function": "Supports a person sitting",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["armchair", "sofa"],
      "required_properties": ["supports person sitting"]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_near_seat",
        "relation": "REFRESHMENT_SETTING IS NEAR SEATING_SPOT",
        "participant_roles": ["refreshment_setting", "seating_spot"]
      ,
        "required": true
      }
    ,
      {
        "id": "control_accessible",
        "relation": "ENTERTAINMENT_CONTROL IS ACCESSIBLE TO SEATING_SPOT",
        "participant_roles": ["entertainment_control", "seating_spot"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment",
        "operation": "PLACE REFRESHMENT_SETTING NEAR SEATING_SPOT",
        "participant_roles": ["refreshment_setting", "seating_spot"],
        "operation_count": 2
      }
    ,
      {
        "id": "move_control",
        "operation": "PLACE ENTERTAINMENT_CONTROL ACCESSIBLE TO SEATING_SPOT",
        "participant_roles": ["entertainment_control", "seating_spot"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "items on desk in foreground", "visual_description": "Two white plates and a red cup"},
        {"label": "cup on coffee table", "visual_description": "Single red cup"}
      ],
      "entertainment_control": [
        {"label": "remote on desk in foreground", "visual_description": "Black remote control"}
      ],
      "television": [
        {"label": "wall-mounted screen", "visual_description": "Large black rectangular screen"}
      ],
      "seating_spot": [
        {"label": "left armchair", "visual_description": "Armchair with black cushion"},
        {"label": "right armchair", "visual_description": "Armchair with black cushion"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_in_foreground",
        "label": "Desk in foreground",
        "visual_description": "Wooden table with shelves underneath",
        "reason": "Contains visible items and shelves; could be a source or storage."
      },
      {
        "id": "console_table_under_tv",
        "label": "Console table under TV",
        "visual_description": "Long wooden table with open shelves",
        "reason": "Open shelves could contain additional items."
      },
      {
        "id": "side_tables",
        "label": "Side tables",
        "visual_description": "Small wooden tables with open shelves",
        "reason": "Open shelves could contain additional items."
      }
    ],
    "inspection_order": [
      "desk_in_foreground",
      "console_table_under_tv",
      "side_tables"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
